const text = String(root.outbound_text || whatsapp.text || root.message || root.reply_text || root.clarifying_question || "Esse número ainda não está liberado no AcerttaPay. Ative o WhatsApp nas Configurações do app.").trim();
return [{ json: { ...root, ok: root.ok !== false, workflow_key: root.workflow_key || "6.1", outbound_text: text, send_by_orchestrator: true, whatsapp: { ...whatsapp, text } } }];

function cleanJsonContent(value) {
  if (value && typeof value === 'object') return value;
  const raw = String(value || '').trim();
  if (!raw) return '';
  const withoutFence = raw.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
  const first = withoutFence.indexOf('{');
  const last = withoutFence.lastIndexOf('}');
  if (first >= 0 && last > first) return withoutFence.slice(first, last + 1);
  return withoutFence;
}
const content = $json.output ?? $json.text ?? $json.response ?? $json.choices?.[0]?.message?.content ?? '';
let parsed;
try {
  const cleaned = cleanJsonContent(content);
  parsed = typeof cleaned === 'object' ? cleaned : JSON.parse(cleaned);
} catch (error) {
  parsed = {
    intent: 'help',
    confidence: 0,
    needs_clarification: false,
    reply_text: 'Posso conferir se o mês pode ser fechado, mostrar pendências e iniciar fechamento ou reabertura com confirmação forte. Ex.: posso fechar junho? 🔎'
  };
}
if (!parsed || typeof parsed !== 'object') parsed = { intent: 'help', reply_text: 'Me manda qual mês você quer conferir para fechamento.' };
const apiIntents = new Set(['month_close_readiness','month_close_blockers','month_close_summary','prepare_month_close','prepare_month_reopen']);
parsed.should_call_api = apiIntents.has(String(parsed.intent || '')) && parsed.needs_clarification !== true;
if (parsed.needs_clarification === true && !parsed.clarifying_question) parsed.clarifying_question = 'Qual mês você quer conferir ou fechar?';
if (['greeting','help'].includes(String(parsed.intent || '')) && !parsed.reply_text) {
  parsed.reply_text = 'Oi! Aqui é seu concierge de fechamento mensal do AcerttaPay. Posso conferir pendências, dizer se o mês pode fechar e iniciar fechamento ou reabertura com confirmação forte. Ex.: *posso fechar junho?* 🔎';
}
if (String(parsed.intent || '') === 'out_of_scope' && !parsed.reply_text) parsed.reply_text = 'Esse pedido parece de outra área do AcerttaPay. Aqui eu cuido só de fechamento mensal: conferência, bloqueadores, fechamento e reabertura com segurança. 🔐';
return [{ json: parsed }];

const root = $json || {};
const whatsapp = root.whatsapp && typeof root.whatsapp === 'object' ? root.whatsapp : {};
const text = String(root.outbound_text || whatsapp.text || root.message || root.reply_text || root.clarifying_question || "Pedido processado no AcerttaPay.").trim();
return [{ json: { ...root, ok: root.ok !== false, workflow_key: root.workflow_key || "6.1", outbound_text: text, send_by_orchestrator: true, whatsapp: { ...whatsapp, text } } }];

const parsed = $json || {};
const intent = String(parsed.intent || '').trim();
const phone = $('Normalize Evolution Payload').first().json.phone;
const source = {
  channel: 'whatsapp',
  instance: $('Normalize Evolution Payload').first().json.instance,
  message_id: $('Normalize Evolution Payload').first().json.message_id,
  raw_text: $('Normalize Evolution Payload').first().json.message_text
};
const period = parsed.period || parsed.query || {};
let endpoint = '/api/automation/v1/month-close/readiness';
