if (intent === 'prepare_month_close') {
  endpoint = '/api/automation/v1/month-close/prepare-close';
} else if (intent === 'prepare_month_reopen') {
  endpoint = '/api/automation/v1/month-close/prepare-reopen';
} else {
  endpoint = '/api/automation/v1/month-close/readiness';
}
const body = { phone, source, period };
return [{ json: {
  intent,
  endpoint,
  body,
  idempotency_key: `whatsapp-month-close:${$('Normalize Evolution Payload').first().json.instance}:${$('Normalize Evolution Payload').first().json.message_id}:${idempotencySuffix}`
} }];

const result = $json || {};
let text = result.whatsapp?.text || result.message || result.reply_text || '';
if (!text) text = 'Fechamento mensal processado no AcerttaPay, mas a resposta veio tímida. Tenta de novo em instantes.';
